content.solution_code:
class ResourceZone {
    #resources;
    #difficulty;

    constructor(initialResources, difficulty) {
        this.#resources = initialResources;
        this.#difficulty = difficulty;
    }

    get difficulty() {
        return this.#difficulty;
    }

    get remainingResources() {
        return this.#resources;
    }

    isEmpty() {
        return this.#resources <= 0;
    }

    collect(amount) {
        if (amount > this.#resources) {
            const collected = this.#resources;
            this.#resources = 0;
            return collected;
        } else {
            this.#resources -= amount;
            return amount;
        }
    }
}

class Harvester {
    #name;
    #efficiency;

    constructor(name, efficiency) {
        this.#name = name;
        this.#efficiency = efficiency;
    }

    harvestFromZone(zone, attempts) {
        let totalCollected = 0;
        if (zone.isEmpty()) {
            // console.log(`${this.#name} found ${zone.remainingResources} resources in the zone. No resources to harvest.`);
            return 0;
        }

        const effectiveCollectionPerAttempt = Math.max(1, Math.floor(this.#efficiency / zone.difficulty));

        for (let i = 0; i < attempts; i++) {
            if (zone.isEmpty()) {
                // console.log(`${this.#name} finished harvesting early. Zone is now empty.`);
                break;
            }
            const collectedThisAttempt = zone.collect(effectiveCollectionPerAttempt);
            totalCollected += collectedThisAttempt;
            // console.log(`${this.#name} collected ${collectedThisAttempt} resources. Zone has ${zone.remainingResources} left.`);
        }
        return totalCollected;
    }
}

